from pathlib import Path
import json,hashlib,shutil,tempfile
root=Path.cwd()
if not (root/'package.json').is_file(): raise SystemExit('Execute na pasta /workspaces/planilha-manel.')
files=json.loads('{"lib/alavancagem.ts": "import type {RecordItem} from \'./banca\';\\nexport type Group=\'alavancagem\'|\'individual\';\\nexport type Entry={group?:Group;sequence:number;cycle:number;stake:number;prize:number;result:\'Pendente\'|\'Green\'|\'Red\';event:string;date:string};\\nexport const leverageEntries=(rows:RecordItem[],group:Group=\'alavancagem\')=>rows.filter(r=>r.kind===\'alavancagem\'&&(r.data.group??\'alavancagem\')===group).map(r=>({...r,data:r.data as Entry})).sort((a,b)=>a.data.sequence-b.data.sequence);\\nexport function nextLeverage(rows:RecordItem[],group:Group=\'alavancagem\'){\\n const entries=leverageEntries(rows,group),last=entries.at(-1);\\n if(last?.data.result===\'Pendente\')throw new Error(\'Finalize a entrada pendente antes de criar outra.\');\\n const reset=!last||last.data.result===\'Red\'||last.data.prize>5000;\\n return {stake:reset?1000:last.data.prize,sequence:(last?.data.sequence||0)+1,cycle:!last?1:last.data.cycle+(reset?1:0)};\\n}\\nexport function settleLeverage(entry:Entry,result:\'Green\'|\'Red\'):Entry{\\n if(entry.result!==\'Pendente\')throw new Error(\'Esta entrada já foi finalizada. Sincronize os dados.\');\\n return {...entry,result,prize:result===\'Green\'?Math.round(entry.stake*130/100):0};\\n}\\n", "app/api/alavancagem/route.ts": "import {z} from \'zod\';\\nimport {database} from \'@/lib/store\';\\nimport type {RecordItem} from \'@/lib/banca\';\\nimport {recordsSnapshot,insertRecordSql,updateRecordSql} from \'@/lib/record-changes\';\\nimport {nextLeverage,settleLeverage} from \'@/lib/alavancagem\';\\nconst input=z.discriminatedUnion(\'action\',[\\n z.object({action:z.literal(\'create\'),group:z.enum([\'alavancagem\',\'individual\']).default(\'alavancagem\'),event:z.string().trim().min(1).max(200),date:z.string().regex(/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/),expectedSequence:z.number().int().positive()}),\\n z.object({action:z.literal(\'settle\'),group:z.enum([\'alavancagem\',\'individual\']).default(\'alavancagem\'),id:z.string().min(1),revision:z.number().int().positive(),result:z.enum([\'Green\',\'Red\'])})\\n]);\\nexport async function POST(req:Request){try{\\n const origin=req.headers.get(\'origin\');if(origin&&origin!==new URL(req.url).origin)return Response.json({error:\'Origem inválida\'},{status:403});\\n const body=input.parse(await req.json());\\n const all=await database().prepare(\'SELECT * FROM records\').all();\\n const rows:RecordItem[]=all.results.map((r:any)=>({...r,data:JSON.parse(r.data)}));\\n const snapshot=recordsSnapshot(rows);\\n let result;\\n if(body.action===\'create\'){\\n  const next=nextLeverage(rows,body.group);\\n  if(next.sequence!==body.expectedSequence)return Response.json({error:\'A sequência mudou. Sincronize antes de registrar.\'},{status:409});\\n  const data={...next,group:body.group,event:body.event,date:body.date,result:\'Pendente\',prize:0};\\n  result=await database().prepare(insertRecordSql).bind(crypto.randomUUID(),\'alavancagem\',JSON.stringify(data),snapshot).run();\\n }else{\\n  const row=rows.find(r=>r.id===body.id&&r.kind===\'alavancagem\'&&(r.data.group??\'alavancagem\')===body.group);\\n  if(!row||row.revision!==body.revision)return Response.json({error:\'A entrada mudou. Sincronize antes de finalizar.\'},{status:409});\\n  const data=settleLeverage(row.data,body.result);\\n  result=await database().prepare(updateRecordSql).bind(JSON.stringify(data),row.id,body.revision,snapshot).run();\\n }\\n if(!result.meta.changes)return Response.json({error:\'Os dados mudaram. Sincronize e confira antes de repetir.\'},{status:409});\\n return Response.json({ok:true},{headers:{\'Cache-Control\':\'no-store\'}});\\n}catch(e){return Response.json({error:e instanceof z.ZodError?\'Confira o evento e a data.\':e instanceof Error?e.message:\'Não foi possível salvar.\'},{status:400});}}\\n", "components/alavancagem.tsx": "\\"use client\\";\\nimport {useRef,useState} from \'react\';\\nimport {Plus} from \'lucide-react\';\\nimport {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from \'@/components/ui/dialog\';\\nimport {money,RecordItem} from \'@/lib/banca\';\\nimport {leverageEntries,nextLeverage,type Group} from \'@/lib/alavancagem\';\\ntype PanelProps={rows:RecordItem[];disabled:boolean;onUpdated:()=>Promise<unknown>};\\nexport function AlavancagemPanel(props:PanelProps){\\n const [group,setGroup]=useState<Group>(\'alavancagem\');\\n return <div>\\n  <div role=\\"tablist\\" aria-label=\\"Registros de alavancagem\\" style={{display:\'flex\',gap:8,flexWrap:\'wrap\',marginBottom:20}}>\\n   {([\'alavancagem\',\'individual\'] as const).map(value=><button type=\\"button\\" role=\\"tab\\" id={\'tab-\'+value} aria-controls={\'panel-\'+value} aria-selected={group===value} key={value} className={group===value?\'primary\':\'secondary\'} onClick={()=>setGroup(value)}>{value===\'alavancagem\'?\'Alavancagem 1,3\':\'Individual\'}</button>)}\\n  </div>\\n  {([\'alavancagem\',\'individual\'] as const).map(value=><div key={value} role=\\"tabpanel\\" id={\'panel-\'+value} aria-labelledby={\'tab-\'+value} hidden={group!==value}><LeverageRegister {...props} group={value}/></div>)}\\n </div>;\\n}\\nfunction LeverageRegister({rows,disabled,onUpdated,group}:PanelProps&{group:Group}){\\n const entries=leverageEntries(rows,group),pending=entries.find(r=>r.data.result===\'Pendente\');\\n const next=pending?null:nextLeverage(rows,group);\\n const [open,setOpen]=useState(false),[event,setEvent]=useState(\'\'),[date,setDate]=useState(\'\'),[error,setError]=useState(\'\'),[busy,setBusy]=useState(false),[confirm,setConfirm]=useState<{id:string;revision:number;result:\'Green\'|\'Red\';event:string;stake:number}|null>(null);\\n const [creation,setCreation]=useState<{stake:number;sequence:number;cycle:number}|null>(null);\\n const lock=useRef(false);\\n async function send(body:unknown){if(lock.current)return;lock.current=true;setBusy(true);setError(\'\');try{\\n  const response=await fetch(\'/api/alavancagem\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(body)});\\n  const data=await response.json();if(!response.ok)throw new Error(data.error||\'Não foi possível salvar.\');\\n  setOpen(false);setConfirm(null);await onUpdated();\\n }catch(e){setError(e instanceof Error?e.message:\'Falha na conexão. Sincronize antes de tentar novamente.\');}finally{lock.current=false;setBusy(false);}}\\n const last=entries.at(-1);\\n return <div>\\n  <p className=\\"hint\\">{group===\'individual\'?\'Registros Individual\':\'Registros Alavancagem 1,3\'} · Histórico e sequência de stakes independentes.</p>\\n  <button type=\\"button\\" className=\\"primary\\" disabled={disabled||busy||!!pending} onClick={()=>{setCreation(next);setEvent(\'\');const now=new Date();setDate([now.getFullYear(),String(now.getMonth()+1).padStart(2,\'0\'),String(now.getDate()).padStart(2,\'0\')].join(\'-\'));setError(\'\');setOpen(true);}}><Plus size={18}/>Nova entrada</button>\\n  <section className=\\"person-balance\\" style={{maxWidth:600,margin:\'20px 0\'}}>\\n   <span>{pending?\'Stake da entrada pendente\':\'Stake da próxima entrada\'} · odd 1,30</span>\\n   <strong>{money(pending?.data.stake??next?.stake??1000)}</strong>\\n   <small>{pending?\'Registre Green ou Red para liberar a próxima entrada.\':last?.data.result===\'Green\'&&last.data.prize>5000?\'Meta ultrapassada! O próximo ciclo começa com R$ 10,00.\':\'Green: reinveste o prêmio total. Red: reinicia em R$ 10,00.\'}</small>\\n  </section>\\n  <p className=\\"hint\\">O prêmio inclui a stake. Ao ultrapassar R$ 50,00, o ciclo termina. Este controle não movimenta os saldos das abas Contas e Bancos.</p>\\n  {error&&!open&&!confirm&&<p className=\\"error\\" role=\\"alert\\">{error}</p>}\\n  <div className=\\"account-grid\\">{[...entries].reverse().map(r=><article key={r.id} className=\\"account-card\\">\\n   <small>Entrada {r.data.sequence} · Ciclo {r.data.cycle} · {r.data.date.split(\'-\').reverse().join(\'/\')}</small>\\n   <h3>{r.data.event}</h3><span className={\'pill \'+(r.data.result===\'Green\'?\'done\':\'\')}>{r.data.result}</span>\\n   <p>Stake: <b>{money(r.data.stake)}</b> · Odd: <b>1,30</b></p>\\n   <small>{r.data.result===\'Pendente\'?\'Prêmio se der Green\':\'Prêmio total\'}</small>\\n   <strong>{money(r.data.result===\'Pendente\'?Math.round(r.data.stake*130/100):r.data.prize)}</strong>\\n   {r.data.result===\'Green\'&&r.data.prize>5000&&<p className=\\"positive\\">Meta ultrapassada · ciclo concluído</p>}\\n   {r.data.result===\'Pendente\'&&<div className=\\"account-actions\\">{([\'Green\',\'Red\'] as const).map(result=><button key={result} type=\\"button\\" disabled={disabled||busy} onClick={()=>{setError(\'\');setConfirm({id:r.id,revision:r.revision,result,event:r.data.event,stake:r.data.stake});}}>{result}</button>)}</div>}\\n  </article>)}</div>\\n  {!entries.length&&<div className=\\"quiet-empty\\">Registre a primeira entrada com stake de R$ 10,00.</div>}\\n  <Dialog open={open} onOpenChange={v=>{if(!busy)setOpen(v);}}><DialogContent className=\\"editor\\"><DialogHeader><DialogTitle>Nova entrada</DialogTitle><DialogDescription>Stake automática de {money(creation?.stake||1000)} · Odd 1,30. A entrada será registrada como pendente.</DialogDescription></DialogHeader><form onSubmit={e=>{e.preventDefault();if(creation)void send({action:\'create\',group,event,date,expectedSequence:creation.sequence});}}>\\n   <label className=\\"field\\">Evento / descrição<input required maxLength={200} value={event} onChange={e=>setEvent(e.target.value)} disabled={busy} placeholder=\\"Ex.: Time A x Time B — seleção\\"/></label>\\n   <label className=\\"field\\">Data<input required type=\\"date\\" value={date} onChange={e=>setDate(e.target.value)} disabled={busy}/></label>\\n   {error&&<p className=\\"error\\" role=\\"alert\\">{error}</p>}<div className=\\"form-actions\\"><button type=\\"button\\" className=\\"secondary\\" disabled={busy} onClick={()=>setOpen(false)}>Cancelar</button><button className=\\"primary\\" disabled={busy||disabled}>{busy?\'Salvando…\':\'Registrar entrada\'}</button></div>\\n  </form></DialogContent></Dialog>\\n  <Dialog open={!!confirm} onOpenChange={v=>{if(!v&&!busy)setConfirm(null);}}><DialogContent><DialogHeader><DialogTitle>Confirmar {confirm?.result}?</DialogTitle><DialogDescription>{confirm?.event} · Prêmio total: {money(confirm?.result===\'Green\'?Math.round(confirm.stake*130/100):0)}. O resultado definirá a próxima stake.</DialogDescription></DialogHeader>{error&&<p className=\\"error\\" role=\\"alert\\">{error}</p>}<div className=\\"form-actions\\"><button className=\\"secondary\\" disabled={busy} onClick={()=>setConfirm(null)}>Cancelar</button><button className=\\"primary\\" disabled={busy||disabled} onClick={()=>{if(confirm)void send({action:\'settle\',group,id:confirm.id,revision:confirm.revision,result:confirm.result});}}>{busy?\'Salvando…\':\'Confirmar resultado\'}</button></div></DialogContent></Dialog>\\n </div>;\\n}\\n"}')
expected=json.loads('{"lib/alavancagem.ts": "4cc1aa11d64d6eb0d65a4a9a7fb4a6947c200454a04ab2c9bf7fbda83c7b315b", "app/api/alavancagem/route.ts": "2c771985d655c7e1ba1722aa4f4cf5218735ca45ec05447695c08107f28001a8", "components/alavancagem.tsx": "459ea51137b280340c723d4ea8beef8e589b3dfcfd205495c499e022883c661a"}')
for name,content in files.items():
 p=root/name
 if not p.is_file(): raise SystemExit('Arquivo ausente: '+name+'. Aplique primeiro adicionar-alavancagem.py.')
 current=p.read_bytes()
 if current!=content.encode() and hashlib.sha256(current).hexdigest()!=expected[name]: raise SystemExit('Arquivo mudou: '+name+'. Envie esse arquivo para adaptar sem perder alteracoes.')
backup=Path(tempfile.mkdtemp(prefix='planilha-subabas-'))
for name,content in files.items():
 p=root/name
 b=backup/name;b.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,b)
 p.write_text(content)
print('Atualizacao aplicada: Alavancagem 1,3 e Individual com registros separados.')
print('Registros anteriores preservados em Alavancagem 1,3.')
print('Backup: '+str(backup))
